#nullable enable
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace LinqToXsd
{
    /// <summary>
    /// Summarises the structure of C# source files into markdown documents, using the Roslyn parsing APIs.
    /// </summary>
    internal static class CodeSummariser
    {
        /// <summary>
        /// The language version that code generated by LinqToXsd is expected to be compatible with. Parsing against this
        /// version also doubles as a check that the generated code does not use newer syntax.
        /// </summary>
        internal static readonly LanguageVersion GeneratedCodeLanguageVersion = LanguageVersion.CSharp8;

        private static readonly Regex WhitespacePattern = new Regex(@"\s+", RegexOptions.Compiled);

        /// <summary>
        /// Reads the given C# source file and returns a markdown summary of the classes and enums it defines.
        /// </summary>
        /// <param name="sourceFile"></param>
        /// <exception cref="InvalidOperationException"><paramref name="sourceFile"/> contains C# syntax errors.</exception>
        public static string Summarise(string sourceFile)
        {
            var sourceCode = File.ReadAllText(sourceFile);
            return SummariseSource(sourceCode, Path.GetFileName(sourceFile));
        }

        /// <summary>
        /// Summarises the classes and enums defined in <paramref name="sourceCode"/>.
        /// Members that are not visible outside their declaring type (private, or default accessibility) are omitted,
        /// as are all method, accessor and constructor bodies. Type validator fields (the static
        /// <c>SimpleTypeValidator</c> instances generated for simple types) are included without their initialisers.
        /// </summary>
        /// <param name="sourceCode"></param>
        /// <param name="sourceFileName">Used for error messages only.</param>
        /// <exception cref="InvalidOperationException"><paramref name="sourceCode"/> contains C# syntax errors.</exception>
        public static string SummariseSource(string sourceCode, string sourceFileName)
        {
            var tree = CSharpSyntaxTree.ParseText(sourceCode, new CSharpParseOptions(GeneratedCodeLanguageVersion));

            var parseErrors = tree.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToArray();
            if (parseErrors.Any()) {
                var errorsText = string.Join(Environment.NewLine, parseErrors.Select(e => "\t" + e.GetMessage()));
                throw new InvalidOperationException(
                    $"'{sourceFileName}' contains {parseErrors.Length} C# parsing error(s):{Environment.NewLine}{errorsText}");
            }

            var markdown = new StringBuilder();
            markdown.AppendLine($"# Summary of `{sourceFileName}`");
            markdown.AppendLine();
            markdown.AppendLine("Generated by `linqtoxsd sum`.");
            markdown.AppendLine();

            foreach (var type in tree.GetRoot().DescendantNodes().OfType<BaseTypeDeclarationSyntax>())
            {
                switch (type)
                {
                    case ClassDeclarationSyntax classDeclaration when TypeIsIncluded(classDeclaration):
                        AppendClassSummary(markdown, classDeclaration);
                        break;
                    case EnumDeclarationSyntax enumDeclaration when TypeIsIncluded(enumDeclaration):
                        AppendEnumSummary(markdown, enumDeclaration);
                        break;
                }
            }

            return markdown.ToString();
        }

        /// <summary>
        /// Types are included when they are not private. Top-level types without a visibility modifier default to
        /// internal in C#, while nested types default to private.
        /// </summary>
        private static bool TypeIsIncluded(BaseTypeDeclarationSyntax type)
        {
            if (type.Modifiers.Any(SyntaxKind.PrivateKeyword)) return false;
            if (IsVisible(type.Modifiers)) return true;
            return !(type.Parent is TypeDeclarationSyntax); // top-level types default to internal
        }

        /// <summary>
        /// True when a member is visible outside its declaring type: public, protected or internal (or combinations
        /// thereof such as protected internal), but never private.
        /// </summary>
        private static bool IsVisible(SyntaxTokenList modifiers)
        {
            if (modifiers.Any(SyntaxKind.PrivateKeyword)) return false;
            return modifiers.Any(SyntaxKind.PublicKeyword)
                || modifiers.Any(SyntaxKind.ProtectedKeyword)
                || modifiers.Any(SyntaxKind.InternalKeyword);
        }

        /// <summary>
        /// Unlike methods, constructors without an access modifier are private by default. Static constructors have no
        /// visibility at all and are always included.
        /// </summary>
        private static bool ConstructorIsIncluded(SyntaxTokenList modifiers)
        {
            if (modifiers.Any(SyntaxKind.PrivateKeyword)) return false;
            return IsVisible(modifiers) || modifiers.Any(SyntaxKind.StaticKeyword);
        }

        private static void AppendClassSummary(StringBuilder markdown, ClassDeclarationSyntax classDeclaration)
        {
            markdown.AppendLine($"## `{GetFullName(classDeclaration)}` — class");
            markdown.AppendLine();
            markdown.AppendLine($"- **Declaration:** `{ClassDeclarationSignature(classDeclaration)}`");
            markdown.AppendLine();

            var constructors = new List<string>();
            var methods = new List<string>();
            var properties = new List<string>();
            var typeValidators = new List<string>();

            foreach (var member in classDeclaration.Members)
            {
                switch (member)
                {
                    case ConstructorDeclarationSyntax constructor when ConstructorIsIncluded(constructor.Modifiers):
                        constructors.Add(ConstructorSignature(constructor));
                        break;
                    case MethodDeclarationSyntax method when IsVisible(method.Modifiers):
                        methods.Add(MethodSignature(method));
                        break;
                    case PropertyDeclarationSyntax property when IsVisible(property.Modifiers):
                        properties.Add(PropertySignature(property));
                        break;
                    case FieldDeclarationSyntax field when IsTypeValidatorField(field):
                        typeValidators.Add(FieldSignature(field));
                        break;
                }
            }

            AppendMembersSection(markdown, "Constructors", constructors);
            AppendMembersSection(markdown, "Methods", methods);
            AppendMembersSection(markdown, "Properties", properties);
            AppendMembersSection(markdown, "Type validators", typeValidators);
        }

        private static void AppendEnumSummary(StringBuilder markdown, EnumDeclarationSyntax enumDeclaration)
        {
            markdown.AppendLine($"## `{GetFullName(enumDeclaration)}` — enum");
            markdown.AppendLine();
            markdown.AppendLine($"- **Declaration:** `{EnumDeclarationSignature(enumDeclaration)}`");
            markdown.AppendLine();

            var values = enumDeclaration.Members.Select(member =>
            {
                var signature = member.Identifier.Text;
                if (member.EqualsValue != null) signature += " = " + Normalise(member.EqualsValue.Value.ToString());
                return signature;
            });

            AppendMembersSection(markdown, "Values", values);
        }

        private static void AppendMembersSection(StringBuilder markdown, string heading, IEnumerable<string> memberSignatures)
        {
            var signatures = memberSignatures.ToArray();
            if (!signatures.Any()) return;

            markdown.AppendLine($"### {heading}");
            markdown.AppendLine();
            foreach (var signature in signatures) markdown.AppendLine($"- `{signature}`");
            markdown.AppendLine();
        }

        /// <summary>
        /// True when a field is a type validator: the static <c>SimpleTypeValidator TypeDefinition</c> fields that the
        /// generator emits into simple type classes. Other fields (XName constants etc.) are not part of the summary.
        /// </summary>
        private static bool IsTypeValidatorField(FieldDeclarationSyntax field)
        {
            if (!IsVisible(field.Modifiers)) return false;
            return field.Declaration.Type.ToString().Contains("SimpleTypeValidator");
        }

        private static string FieldSignature(FieldDeclarationSyntax field)
        {
            var names = string.Join(", ", field.Declaration.Variables.Select(v => v.Identifier.Text));
            return Normalise($"{ModifiersText(field.Modifiers)} {field.Declaration.Type} {names}");
        }

        private static string ClassDeclarationSignature(ClassDeclarationSyntax classDeclaration)
        {
            var signature = $"{ModifiersText(classDeclaration.Modifiers)} class {classDeclaration.Identifier}";
            signature += Normalise(classDeclaration.TypeParameterList?.ToString() ?? string.Empty);
            var baseList = Normalise(classDeclaration.BaseList?.ToString() ?? string.Empty);
            if (!string.IsNullOrEmpty(baseList)) signature += " " + baseList;
            foreach (var constraint in classDeclaration.ConstraintClauses) signature += " " + Normalise(constraint.ToString());
            return Normalise(signature);
        }

        private static string EnumDeclarationSignature(EnumDeclarationSyntax enumDeclaration)
        {
            var signature = $"{ModifiersText(enumDeclaration.Modifiers)} enum {enumDeclaration.Identifier}";
            var baseList = Normalise(enumDeclaration.BaseList?.ToString() ?? string.Empty);
            if (!string.IsNullOrEmpty(baseList)) signature += " " + baseList;
            return Normalise(signature);
        }

        private static string MethodSignature(MethodDeclarationSyntax method)
        {
            var signature = $"{ModifiersText(method.Modifiers)} {method.ReturnType} {ExplicitInterfaceSpecifier(method.ExplicitInterfaceSpecifier)}{method.Identifier}{method.TypeParameterList}({ParameterListSignature(method.ParameterList)})";
            foreach (var constraint in method.ConstraintClauses) signature += " " + Normalise(constraint.ToString());
            return Normalise(signature);
        }

        private static string ConstructorSignature(ConstructorDeclarationSyntax constructor)
        {
            var signature = $"{ModifiersText(constructor.Modifiers)} {constructor.Identifier}({ParameterListSignature(constructor.ParameterList)})";
            if (constructor.Initializer != null) signature += " " + Normalise(constructor.Initializer.ToString());
            return Normalise(signature);
        }

        private static string PropertySignature(PropertyDeclarationSyntax property)
        {
            var accessors = string.Empty;
            if (property.AccessorList != null) {
                accessors = " { " + string.Join(" ", property.AccessorList.Accessors.Select(AccessorSignature)) + " }";
            } else if (property.ExpressionBody != null) {
                accessors = " { get; }"; // an expression-bodied property is a getter with an elided body
            }

            return Normalise($"{ModifiersText(property.Modifiers)} {property.Type} {ExplicitInterfaceSpecifier(property.ExplicitInterfaceSpecifier)}{property.Identifier}{accessors}");
        }

        private static string AccessorSignature(AccessorDeclarationSyntax accessor)
        {
            // accessor modifiers are rendered as-is; e.g. a private setter on a public property stays 'private set;'
            var modifiers = string.Join(" ", accessor.Modifiers.Select(m => m.Text));
            return Normalise($"{modifiers} {accessor.Keyword.Text};");
        }

        private static string ParameterListSignature(ParameterListSyntax parameterList)
        {
            return string.Join(", ", parameterList.Parameters.Select(ParameterSignature));
        }

        private static string ParameterSignature(ParameterSyntax parameter)
        {
            var parts = new List<string>();
            parts.AddRange(parameter.Modifiers.Select(m => m.Text));
            if (parameter.Type != null) parts.Add(Normalise(parameter.Type.ToString()));
            parts.Add(parameter.Identifier.Text);

            var signature = string.Join(" ", parts);
            if (parameter.Default != null) signature += " = " + Normalise(parameter.Default.Value.ToString());
            return signature;
        }

        private static string ExplicitInterfaceSpecifier(ExplicitInterfaceSpecifierSyntax? specifier)
        {
            return specifier != null ? specifier.ToString() : string.Empty;
        }

        /// <summary>
        /// Builds the fully qualified name of a type: enclosing namespaces and containing types, followed by the type name.
        /// </summary>
        private static string GetFullName(BaseTypeDeclarationSyntax type)
        {
            var nameParts = new List<string>();
            for (var ancestor = type.Parent; ancestor != null; ancestor = ancestor.Parent)
            {
                switch (ancestor)
                {
                    case NamespaceDeclarationSyntax nameSpace:
                        nameParts.Add(nameSpace.Name.ToString());
                        break;
                    case TypeDeclarationSyntax containingType:
                        nameParts.Add(containingType.Identifier.Text);
                        break;
                }
            }

            nameParts.Reverse();
            nameParts.Add(type.Identifier.Text);
            return string.Join(".", nameParts);
        }

        /// <summary>
        /// Renders the modifier tokens of a declaration as they appear in source, minus any 'private' modifier.
        /// </summary>
        private static string ModifiersText(SyntaxTokenList modifiers)
        {
            return string.Join(" ", modifiers.Where(m => !m.IsKind(SyntaxKind.PrivateKeyword)).Select(m => m.Text));
        }

        private static string Normalise(string text)
        {
            return WhitespacePattern.Replace(text, " ").Trim();
        }
    }
}
